const STORE='studyquest.v1';
const iconMap={Dashboard:'⌂',Quests:'✦',Certificates:'▧',Leaderboard:'♙',Notifications:'♧',Settings:'⚙',Administration:'♜'};
const seed={brand:{name:'StudyQuest',logo:'',contact:'hello@studyquest.app',accent:'#7258e8'},users:[{id:'u1',firstName:'Alex',lastName:'Morgan',email:'alex@studyquest.demo',password:'studyquest',role:'learner',active:true,avatar:'',bio:'Curious learner on a mission to master new ideas.',country:'Liberia',phone:'',joined:'2026-09-22',xp:1280,streak:5,bestStreak:9,notifications:true},{id:'u2',firstName:'Maya',lastName:'Johnson',email:'maya@studyquest.demo',password:'studyquest',role:'learner',active:true,avatar:'',bio:'Learning something new every day.',country:'Ghana',phone:'',joined:'2026-09-29',xp:920,streak:3,bestStreak:6,notifications:true},{id:'u3',firstName:'Jordan',lastName:'Lee',email:'jordan@studyquest.demo',password:'studyquest',role:'learner',active:true,avatar:'',bio:'Future developer.',country:'Nigeria',phone:'',joined:'2026-10-04',xp:640,streak:1,bestStreak:4,notifications:true},{id:'u4',firstName:'Sam',lastName:'Rivera',email:'sam@studyquest.demo',password:'studyquest',role:'learner',active:false,avatar:'',bio:'',country:'',phone:'',joined:'2026-10-11',xp:180,streak:0,bestStreak:2,notifications:false},{id:'admin',firstName:'StudyQuest',lastName:'Admin',email:'admin@studyquest.demo',password:'admin123',role:'admin',active:true,avatar:'',bio:'',country:'',phone:'',joined:'2026-09-01',xp:0,streak:0,bestStreak:0,notifications:true}],quests:[{id:'q1',owner:'u1',title:'The Solar System',topic:'Astronomy',icon:'🪐',color:'qa-blue',description:'Explore the planets, our star and the cosmic neighborhood we call home.',levels:4,minutes:18,xp:220,progress:75,status:'In progress',questions:[{question:'Which planet has the most prominent ring system?',answers:['Mars','Saturn','Venus','Mercury'],correct:1,explain:'Saturn is famous for its wide, bright rings made mostly of ice and rock.'},{question:'What is the closest star to Earth?',answers:['Sirius','Proxima Centauri','The Sun','Betelgeuse'],correct:2,explain:'The Sun is our nearest star, about 150 million kilometers away.'},{question:'Which planet is known as the Red Planet?',answers:['Jupiter','Mars','Neptune','Uranus'],correct:1,explain:'Iron-rich dust gives Mars its reddish color.'}]},{id:'q2',owner:'u1',title:'JavaScript Essentials',topic:'Programming',icon:'💻',color:'qa-peach',description:'Build a strong foundation in the language that powers the web.',levels:5,minutes:24,xp:300,progress:42,status:'In progress',questions:[{question:'Which keyword declares a block-scoped variable that can be reassigned?',answers:['const','let','static','define'],correct:1,explain:'let creates a block-scoped variable that can be reassigned.'},{question:'What does Array.map() return?',answers:['A new transformed array','The original array','A boolean','An object'],correct:0,explain:'map returns a new array containing the result of calling your function on each item.'},{question:'Which value represents the absence of an assigned value?',answers:['0','false','undefined','NaN'],correct:2,explain:'undefined is the default value of a declared variable without an assignment.'}]},{id:'q3',owner:'u1',title:'The Art of Storytelling',topic:'Writing',icon:'✍️',color:'qa-green',description:'Discover character, conflict and the craft behind stories that stay with us.',levels:3,minutes:14,xp:150,progress:100,status:'Complete',questions:[]}],certificates:[{id:'c1',owner:'u1',questTitle:'The Art of Storytelling',score:92,issued:'2026-10-12',code:'SQ-7F2A9C'},{id:'c2',owner:'u1',questTitle:'Creative Writing Basics',score:88,issued:'2026-10-08',code:'SQ-4D8B1E'}],notifications:[{id:'n1',owner:'u1',icon:'🏆',title:'A new badge is yours!',body:'You earned the Perfect Score badge. Keep that momentum going.',when:'2 hours ago',read:false},{id:'n2',owner:'u1',icon:'✦',title:'Your next quest is waiting',body:'Your solar system adventure is ready whenever you are.',when:'Yesterday',read:false},{id:'n3',owner:'u1',icon:'🎓',title:'Certificate unlocked',body:'Your Storytelling certificate is ready to share.',when:'Oct 12',read:true}],activity:[24,32,20,48,38,66,49,58,75,61,82,70,88,74],badges:[{icon:'🚀',name:'First Quest',detail:'Quest created',earned:true},{icon:'🎯',name:'Perfect Score',detail:'100% on a level',earned:true},{icon:'🔥',name:'On Fire',detail:'3 day streak',earned:true},{icon:'🧠',name:'Quick Thinker',detail:'10 answers right',earned:true},{icon:'📚',name:'Bookworm',detail:'5 quests finished',earned:false},{icon:'🌟',name:'Quest Master',detail:'Reach 2,000 XP',earned:false},{icon:'🏅',name:'Early Bird',detail:'Learn before 8am',earned:false},{icon:'💎',name:'Legend',detail:'Complete 20 quests',earned:false}]};
let db=loadDb(),user=db.users.find(u=>u.id===sessionStorage.getItem('sq.user'))||null,page='Dashboard',mobileOpen=false,questMode='topic',activeQuiz=null,quizStep=0,quizAnswers=[],profileTab='profile',adminQuery='',certSelected=null;
function loadDb(){try{return JSON.parse(localStorage.getItem(STORE))||structuredClone(seed)}catch{return structuredClone(seed)}}
function save(){localStorage.setItem(STORE,JSON.stringify(db))}
function setUser(u){user=u;sessionStorage.setItem('sq.user',u?.id||'');render()}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fullName(u=user){return [u?.firstName,u?.lastName].filter(Boolean).join(' ')||u?.email||'Learner'}
function initials(u=user){return `${u?.firstName?.[0]||''}${u?.lastName?.[0]||u?.email?.[0]||''}`.toUpperCase()}
function brandLogo(){return db.brand.logo?`<span class="brand-mark brand-logo"><img src="${esc(db.brand.logo)}" alt=""></span>`:`<span class="brand-mark">✦</span>`}
function brandName(){let [first,...rest]=db.brand.name.trim().split(/\s+/);return `${esc(first||'Study')}<em>${esc(rest.join(' ')||'Quest')}</em>`}
function avatar(u=user,cls='avatar'){return `<div class="${cls}">${u?.avatar?`<img src="${esc(u.avatar)}" alt="${esc(fullName(u))}">`:esc(initials(u))}</div>`}
function toast(msg,type='success'){const t=document.createElement('div');t.className=`toast ${type}`;t.textContent=msg;document.querySelector('#toast-region').append(t);setTimeout(()=>t.remove(),3000)}
function level(xp){return xp>=1500?['Master',1500,2400]:xp>=600?['Scholar',600,1500]:xp>=200?['Explorer',200,600]:['Rookie',0,200]}
function ownedQuests(){return db.quests.filter(q=>q.owner===user?.id)}
function myCerts(){return db.certificates.filter(c=>c.owner===user?.id)}
function myNotices(){return db.notifications.filter(n=>n.owner===user?.id)}
function navLink(name){let count=name==='Notifications'?myNotices().filter(n=>!n.read).length:0;return `<a href="#${name.toLowerCase()}" class="nav-item ${page===name?'active':''}" data-page="${name}"><span class="nav-icon">${iconMap[name]}</span>${name}${count?`<span class="nav-badge">${count}</span>`:''}</a>`}
function shell(content){let nav=['Dashboard','Quests','Certificates','Leaderboard','Notifications','Settings'];if(user?.role==='admin')nav.push('Administration');let mob=['Dashboard','Quests','Certificates','Leaderboard','Settings'];return `<div class="app-shell"><aside class="sidebar ${mobileOpen?'open':''}"><a class="brand" href="#dashboard" data-page="Dashboard">${brandLogo()}<span>${brandName()}</span></a><div class="nav-label">LEARN</div>${nav.slice(0,4).map(navLink).join('')}<div class="nav-label">YOUR SPACE</div>${nav.slice(4).map(navLink).join('')}<div class="sidebar-bottom"><div class="sidebar-promo"><b>Your next big win is close</b><p>Keep your streak alive and reach the next level.</p><button data-page="Quests">Explore quests&nbsp; →</button></div><a class="nav-item" href="#landing" data-action="landing"><span class="nav-icon">↗</span>View landing page</a><button class="nav-item" data-action="logout" style="width:100%;border:0;background:transparent;text-align:left"><span class="nav-icon">⇥</span>Sign out</button></div></aside><main class="main"><header class="topbar"><div style="display:flex;align-items:center;gap:12px"><button class="icon-btn menu-btn" data-action="menu" aria-label="Open menu">☰</button><div class="crumb">Study space&nbsp; / &nbsp;<strong>${esc(page)}</strong></div></div><div class="top-actions"><button class="icon-btn" data-page="Notifications" aria-label="Notifications">♧${myNotices().some(n=>!n.read)?'<i class="notify-dot"></i>':''}</button><button class="user-mini" style="border:0;background:transparent" data-page="Settings">${avatar(user,'avatar small')}<span class="user-mini-text"><b>${esc(fullName())}</b><span>${esc(level(user.xp)[0])} · Level ${Math.floor(user.xp/200)+1}</span></span></button></div></header><section class="page">${content}</section></main><nav class="mobile-nav">${mob.map(n=>`<a href="#${n.toLowerCase()}" data-page="${n}" class="${page===n?'active':''}"><span>${iconMap[n]}</span>${n==='Dashboard'?'Home':n}</a>`).join('')}</nav></div>`}
function greeting(){let h=new Date().getHours();return h<12?'Good morning':h<18?'Good afternoon':'Good evening'}
function dashboard(){const qs=ownedQuests(),certs=myCerts(),done=qs.filter(q=>q.status==='Complete').length,first=level(user.xp),percent=Math.min(100,Math.round((user.xp-first[1])/(first[2]-first[1])*100));return `<div class="greeting"><div><span class="eyebrow">${greeting()}, ${esc(user.firstName)} ✨</span><h1>Ready for your next win?</h1><p>Every little step is a big move toward your goals.</p></div><button class="btn btn-primary" data-action="new-quest">＋&nbsp; Create a quest</button></div><div class="grid stats-grid"><div class="card stat-card"><div class="stat-head"><span class="stat-label">Total experience</span><i class="stat-icon ic-lav">✧</i></div><div class="stat-value">${user.xp.toLocaleString()} <span style="font-size:12px;color:#a1a3b2">XP</span></div><div class="stat-foot"><span class="trend">↗ 12%</span> this week</div></div><div class="card stat-card"><div class="stat-head"><span class="stat-label">Current streak</span><i class="stat-icon ic-peach">🔥</i></div><div class="stat-value">${user.streak} <span style="font-size:12px;color:#a1a3b2">days</span></div><div class="stat-foot">Your best is ${user.bestStreak} days. Keep it up!</div></div><div class="card stat-card"><div class="stat-head"><span class="stat-label">Quests completed</span><i class="stat-icon ic-mint">✦</i></div><div class="stat-value">${done}<span style="font-size:13px;color:#a1a3b2"> / ${qs.length}</span></div><div class="stat-foot">You’re building a great habit</div></div><div class="card stat-card"><div class="stat-head"><span class="stat-label">Certificates</span><i class="stat-icon ic-yellow">▧</i></div><div class="stat-value">${certs.length}</div><div class="stat-foot">${certs.length?'Your achievements, all in one place':'Your first one is waiting'}</div></div></div><div class="grid hero-grid"><div class="card welcome-card"><div class="welcome-copy"><span class="eyebrow">YOUR LEARNING JOURNEY</span><h2>You’re on your way to ${first[0]} rank!</h2><p>Earn ${Math.max(0,first[2]-user.xp)} more XP to unlock your next level. You’ve got this.</p><button class="btn btn-white" data-page="Quests">Continue learning&nbsp; →</button></div><div class="welcome-art">🧙</div></div><div class="card streak-card"><div class="streak-head"><h3>Weekly streak</h3><span class="flame">🔥</span></div><p>You’re showing up. That’s what counts!</p><div class="days">${['M','T','W','T','F','S','S'].map((d,i)=>`<div class="day ${i<Math.min(user.streak,5)?'done':''} ${i===Math.min(user.streak,5)?'today':''}"><i>${i<user.streak?'✓':d}</i>${d}</div>`).join('')}</div></div></div><div class="grid chart-grid"><div class="card card-pad"><div class="card-title-row"><div><h3>Your learning progress</h3><span class="subtle">A little progress adds up</span></div><select class="select-mini" id="chart-range"><option>Last 14 days</option><option>Last 7 days</option></select></div><div class="chart-area"><canvas id="progress-chart" aria-label="XP earned over the last 14 days"></canvas></div><div class="chart-legend"><span><i class="legend-dot"></i> XP earned</span><span><i class="legend-dot alt"></i> Quests completed</span></div></div><div class="card card-pad activity-card"><div class="card-title-row"><div><h3>Learning mix</h3><span class="subtle">Time across your topics</span></div><span class="subtle">This month</span></div><div class="ring-wrap"><div class="ring"><div class="ring-inner"><b>${qs.length}h</b><span>learning time</span></div></div><div class="legend-list"><span class="legend-item"><i style="background:#7258e8"></i>Science&nbsp; 43%</span><span class="legend-item"><i style="background:#9c82f3"></i>Technology&nbsp; 26%</span><span class="legend-item"><i style="background:#caf0dc"></i>Creative&nbsp; 19%</span><span class="legend-item"><i style="background:#eff0f5"></i>Other&nbsp; 12%</span></div></div></div></div><div class="grid lower-grid"><div class="card card-pad"><div class="card-title-row"><h3>Pick up where you left off</h3><button class="btn btn-soft" data-page="Quests" style="padding:8px 11px;font-size:10px">All quests&nbsp; →</button></div>${qs.slice(0,3).map(q=>`<div class="quest-row"><div class="quest-art ${q.color}">${esc(q.icon)}</div><div class="quest-info"><b>${esc(q.title)}</b><span>${esc(q.topic)} · ${q.levels} levels</span><div class="progress ${q.progress===100?'progress-green':''}"><span style="width:${q.progress}%"></span></div></div><div class="quest-trailing"><b>${q.progress}%</b><span>complete</span></div></div>`).join('')||empty('✦','Your first quest starts here','Turn a topic or your notes into a fun learning adventure.','new-quest')}</div><div class="card card-pad"><div class="card-title-row"><h3>Your badge shelf</h3><span class="subtle">${db.badges.filter(b=>b.earned).length} earned</span></div><div class="badge-grid">${db.badges.slice(0,8).map(b=>`<div class="badge-item" style="${b.earned?'':'opacity:.42;filter:grayscale(1)'}"><i>${b.icon}</i><b>${esc(b.name)}</b><span>${esc(b.detail)}</span></div>`).join('')}</div></div></div>`}
function empty(icon,title,text,action){return `<div class="empty-state"><i>${icon}</i><h3>${title}</h3><p>${text}</p>${action?`<button class="btn btn-primary" data-action="${action}">Get started</button>`:''}</div>`}
function questsPage(){return `<div class="page-title-row"><div><span class="eyebrow">LEARN BY PLAYING</span><h1>Your quests</h1><p>Every quest makes the next challenge feel easier.</p></div><button class="btn btn-primary" data-action="new-quest">＋ Create a quest</button></div>${ownedQuests().length?`<div class="grid quest-grid">${ownedQuests().map(q=>`<article class="card quest-card"><div class="quest-card-top"><div class="quest-card-icon ${q.color}">${esc(q.icon)}</div><span class="tag ${q.status==='Complete'?'complete':''}">${esc(q.status)}</span></div><h3>${esc(q.title)}</h3><p>${esc(q.description)}</p><div class="quest-meta"><span>▤ ${q.levels} levels</span><span>◷ ${q.minutes} min</span><span>✧ ${q.xp} XP</span></div><div class="progress ${q.progress===100?'progress-green':''}"><span style="width:${q.progress}%"></span></div><div class="quest-card-foot"><span>${q.progress}% complete</span><button class="btn ${q.progress===100?'btn-soft':'btn-primary'}" style="padding:8px 12px;font-size:10px" data-action="play" data-id="${q.id}">${q.progress===100?'Play again':'Continue'}&nbsp; →</button></div></article>`).join('')}</div>`:empty('✦','No quests yet','Create a quest from your notes or any topic you want to explore.','new-quest')}`}
function newQuestModal(){return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="new-quest-title"><div class="modal-head"><div><h3 id="new-quest-title">Build your next adventure</h3><span class="subtle">Pick a topic, add your notes, and let’s play.</span></div><button class="modal-close" data-action="close-modal" aria-label="Close">✕</button></div><div class="segmented"><button class="segment ${questMode==='topic'?'active':''}" data-mode="topic">✦ &nbsp;A topic</button><button class="segment ${questMode==='notes'?'active':''}" data-mode="notes">▤ &nbsp;My notes</button><button class="segment ${questMode==='file'?'active':''}" data-mode="file">↥ &nbsp;Upload</button></div><form id="quest-form"><div class="field"><label for="quest-title">${questMode==='topic'?'What would you like to learn?':'Give your quest a title'}</label><input id="quest-title" name="title" required maxlength="70" placeholder="e.g. Photosynthesis, web design, world history"></div>${questMode==='notes'?'<div class="field"><label for="quest-notes">Paste your study notes</label><textarea id="quest-notes" name="notes" required maxlength="6000" placeholder="Paste a summary, class notes, or key ideas you want to remember…"></textarea><small>Up to 6,000 characters</small></div>':''}${questMode==='file'?'<div class="field"><label for="quest-file">Upload notes from your device</label><div class="upload-box">📄<b>Choose a text or PDF file</b>Files stay in this browser demo<input id="quest-file" name="file" type="file" accept=".txt,.pdf,text/plain,application/pdf"></div><div class="field" style="margin-top:12px"><label for="file-topic">What should this quest be called?</label><input id="file-topic" name="filetopic" placeholder="e.g. My biology revision"></div></div>':''}<div class="field"><label for="quest-icon">Adventure mood</label><select id="quest-icon" name="icon"><option value="🪐">🪐 Cosmic explorer</option><option value="🧪">🧪 Curious scientist</option><option value="💻">💻 Digital creator</option><option value="📚">📚 Story seeker</option><option value="🌱">🌱 Nature guide</option><option value="🎨">🎨 Creative thinker</option></select></div><div class="inline-note">✨ Your quest includes three learning challenges, a quick quiz, XP and progress tracking. Add AI keys in the deployment guide to turn on generated lesson content.</div><div style="display:flex;justify-content:flex-end;margin-top:17px"><button class="btn btn-primary" type="submit">Create my quest&nbsp; →</button></div></form></div></div>`}
async function startQuest(e){e.preventDefault();let f=new FormData(e.target),file=document.querySelector('#quest-file')?.files?.[0],title=(f.get('title')||f.get('filetopic')||'').trim();if(file&&!title)title=file.name.replace(/\.[^.]+$/,'');const topic=questMode==='topic'?title:title.replace(/^(my|notes on)\s+/i,'');let notes=String(f.get('notes')||'');if(file&&file.type==='text/plain'){let r=new FileReader();r.onload=()=>createQuest(title||file.name,topic,String(r.result).slice(0,6000),f.get('icon'));r.readAsText(file);return}if(file&&file.type==='application/pdf'){let button=e.target.querySelector('button[type="submit"]');button.disabled=true;button.innerHTML='<span class="loading"><i class="spinner"></i> Reading your notes…</span>';try{const pdfjs=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs';const doc=await pdfjs.getDocument({data:await file.arrayBuffer()}).promise;let parts=[];for(let n=1;n<=Math.min(doc.numPages,20);n++){const page=await doc.getPage(n),content=await page.getTextContent();parts.push(content.items.map(x=>x.str).join(' '))}notes=parts.join('\n').slice(0,6000);if(!notes.trim())throw new Error('No selectable text was found in this PDF.');createQuest(title||file.name,topic,notes,f.get('icon'))}catch(err){toast(err.message==='Failed to fetch'?'Could not load PDF reader. Try a .txt file or paste your notes.':`Could not read that PDF: ${err.message}`,'error');button.disabled=false;button.textContent='Create my quest →'}return}createQuest(title,topic,notes,f.get('icon'))}
function createQuest(title,topic,notes,emoji){if(!title.trim()){toast('Add a topic or quest title first.','error');return}const q={id:'q'+crypto.randomUUID().slice(0,8),owner:user.id,title,topic:topic||title,icon:emoji,color:['qa-blue','qa-peach','qa-green'][Math.floor(Math.random()*3)],description:notes?`A personalized adventure built from your notes about ${topic||title}.`:`A bite-sized adventure to explore ${topic||title}, practice what you learn, and build confidence.`,levels:4,minutes:16,xp:220,progress:0,status:'Ready',questions:makeQuestions(topic||title,notes)};db.quests.unshift(q);user.xp+=20;user.streak=Math.max(user.streak,1);user.bestStreak=Math.max(user.bestStreak,user.streak);db.badges.find(b=>b.name==='First Quest').earned=true;db.notifications.unshift({id:crypto.randomUUID(),owner:user.id,icon:'✦',title:'Your new quest is ready!',body:`${title} is ready whenever you are.`,when:'Just now',read:false});save();closeModal();navigate('Quests');toast('Your quest is ready. +20 XP!')}
function makeQuestions(topic,notes){let pool=[{question:`What is a useful first step when learning about ${topic}?`,answers:['Break the topic into smaller ideas','Memorize every detail at once','Skip the fundamentals','Avoid examples'],correct:0,explain:'Breaking a topic into smaller ideas makes it easier to understand and remember.'},{question:`Which approach helps you remember new ideas about ${topic}?`,answers:['Explain the idea in your own words','Read without checking understanding','Study only once','Ignore practice questions'],correct:0,explain:'Explaining an idea in your own words is an effective way to check and strengthen understanding.'},{question:`How can you check your understanding of ${topic}?`,answers:['Try a practice question','Avoid applying what you learned','Only reread the title','Skip reviewing mistakes'],correct:0,explain:'Practice questions reveal what you understand and what to review next.'}];if(notes){let clean=notes.replace(/\s+/g,' ').trim(),phrases=clean.split(/[.!?;]\s+/).filter(x=>x.length>18);if(phrases.length){pool[0].question=`Which idea appears in your notes about ${topic}?`;pool[0].answers=[phrases[0].slice(0,95),`An unrelated idea about ${topic}`,`A fact your notes do not mention`,`None of the above`];pool[0].correct=0;pool[0].explain=`Your notes say: “${phrases[0].slice(0,155)}.”`}}return pool}
function playQuest(id){let q=db.quests.find(x=>x.id===id);if(!q)return;activeQuiz=q;quizStep=0;quizAnswers=[];page='Play quest';render()}
function quizPage(){if(!activeQuiz)return questsPage();let q=activeQuiz,question=q.questions?.[quizStep]||{question:`What helps you make steady progress with ${q.topic}?`,answers:['Practice regularly and review what you learn','Wait until you know everything','Skip the basics','Avoid feedback'],correct:0,explain:'Regular practice and reflection help learning stick.'},selected=quizAnswers[quizStep],checked=selected!==undefined;return `<div class="page-title-row"><div><button class="btn btn-outline" data-page="Quests" style="margin-bottom:12px;padding:9px 12px">←&nbsp; Back to quests</button><span class="eyebrow" style="display:block">${esc(q.topic)} ADVENTURE</span><p style="margin-top:5px">A new level is a new chance to grow.</p></div><span class="tag">✧ &nbsp;${user.xp} XP</span></div><div class="card quiz-card"><div class="quiz-progress"><span>Challenge ${quizStep+1} of ${q.questions.length}</span><span>${Math.round(quizStep/q.questions.length*100)}% complete</span></div><div class="progress"><span style="width:${Math.round(quizStep/q.questions.length*100)}%"></span></div><h2>${esc(question.question)}</h2><div class="answer-list">${question.answers.map((a,i)=>`<button class="answer ${selected===i?'chosen':''} ${checked&&i===question.correct?'correct':''} ${checked&&selected===i&&i!==question.correct?'wrong':''}" data-answer="${i}" ${checked?'disabled':''}><span class="answer-key">${String.fromCharCode(65+i)}</span>${esc(a)}</button>`).join('')}</div>${checked?`<div class="inline-note" style="margin-top:14px">${selected===question.correct?'🌟 Nailed it! ':'💡 Keep going. '}${esc(question.explain)}</div>`:''}<div class="quiz-footer"><span class="subtle">${checked?(selected===question.correct?'You earned 10 XP for this answer.':'You can do this!'): 'Take a breath and choose your best answer.'}</span>${checked?`<button class="btn btn-primary" data-action="next-question">${quizStep===q.questions.length-1?'Finish adventure':'Next question'}&nbsp; →</button>`:`<span class="subtle">Your answer</span>`}</div></div>`}
function finishQuiz(){let correct=quizAnswers.reduce((n,a,i)=>n+(a===activeQuiz.questions[i].correct?1:0),0),score=Math.round(correct/activeQuiz.questions.length*100),q=activeQuiz,firstComplete=q.status!=='Complete';q.progress=100;q.status='Complete';q.xp=score>=60?Math.max(q.xp,150):50;user.xp+=score>=60?(firstComplete?150:20):10;user.streak++;user.bestStreak=Math.max(user.streak,user.bestStreak);user.lastActive=new Date().toISOString();db.activity.push(Math.round(score/4));db.activity=db.activity.slice(-14);if(score===100)db.badges.find(b=>b.name==='Perfect Score').earned=true;if(user.streak>=3)db.badges.find(b=>b.name==='On Fire').earned=true;db.notifications.unshift({id:crypto.randomUUID(),owner:user.id,icon:'🎉',title:score>=60?'Quest complete!':'Quest finished!',body:`You scored ${score}% on ${q.title} and earned ${user.xp?150:0} XP.`,when:'Just now',read:false});if(score>=60&&!db.certificates.some(c=>c.owner===user.id&&c.questTitle===q.title)){let cert={id:crypto.randomUUID(),owner:user.id,questTitle:q.title,score,issued:new Date().toISOString().slice(0,10),code:'SQ-'+crypto.randomUUID().slice(0,6).toUpperCase()};db.certificates.unshift(cert);certSelected=cert.id}save();activeQuiz=null;page=score>=60?'Certificates':'Quests';render();toast(score>=60?`Quest complete! ${score}% · Certificate unlocked 🎓`:`Quest finished! ${score}%. Try again to earn a certificate.`)}
function certsPage(){let certs=myCerts();return `<div class="page-title-row"><div><span class="eyebrow">PROUD OF YOUR PROGRESS</span><h1>Your certificates</h1><p>Every certificate is a milestone worth sharing.</p></div></div>${certs.length?`<div class="grid certificate-grid">${certs.map(c=>`<article class="card certificate-card"><div class="cert-preview"><div class="cert-brand">${esc(db.brand.name)} · Certificate of achievement</div><div class="cert-ribbon">🏅</div>${user.avatar?`<img class="cert-avatar" src="${esc(user.avatar)}" alt="${esc(fullName())}">`:`<div class="cert-avatar cert-initials">${esc(initials())}</div>`}<h3>${esc(fullName())}</h3><p>has completed the learning quest</p><p style="font-size:13px;color:#fff">${esc(c.questTitle)}</p><p>Score ${c.score}% &nbsp;·&nbsp; ${new Date(c.issued+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}</p></div><div class="cert-actions"><div><b>${esc(c.questTitle)}</b><span>Certificate ID · ${esc(c.code)}</span></div><button class="btn btn-soft" data-action="print-cert" data-id="${c.id}" style="padding:8px 10px;font-size:10px">↧&nbsp; View & print</button></div></article>`).join('')}</div>`:empty('🎓','Your first certificate is close','Complete a quest with 60% or higher to earn a certificate.','Quests')}`}
function leaderboard(){return `<div class="page-title-row"><div><span class="eyebrow">A LITTLE FRIENDLY MOTIVATION</span><h1>Quest leaderboard</h1><p>Celebrate the progress everyone is making.</p></div><span class="tag">This week</span></div><div class="grid two-col"><div class="card card-pad"><div class="card-title-row"><h3>Top learners</h3><span class="subtle">Ranked by experience</span></div>${[...db.users].filter(x=>x.role==='learner'&&x.active).sort((a,b)=>b.xp-a.xp).map((u,i)=>`<div class="leaderboard-row"><div class="rank">${['01','02','03','04'][i]||String(i+1).padStart(2,'0')}</div>${avatar(u,'avatar small')}<div><b>${esc(fullName(u))}${u.id===user.id?' · You':''}</b><small>${esc(level(u.xp)[0])} · ${u.streak} day streak</small></div><strong>${u.xp.toLocaleString()} XP</strong></div>`).join('')}</div><div class="card card-pad"><div class="card-title-row"><h3>Your rank</h3><span>✨</span></div><div class="empty-state" style="padding:20px 8px"><i>🏅</i><h3>Keep your momentum going</h3><p>You’re in the top ${Math.max(1,Math.ceil(100/db.users.filter(x=>x.role==='learner'&&x.active).length))}% of learners this week. One more quest could move you up!</p><button class="btn btn-primary" data-page="Quests">Play a quest</button></div></div></div>`}
function noticesPage(){let ns=myNotices();return `<div class="page-title-row"><div><span class="eyebrow">YOUR LEARNING UPDATES</span><h1>Notifications</h1><p>Good things happen when you keep showing up.</p></div><button class="btn btn-outline" data-action="read-all">Mark all read</button></div><div class="card card-pad"><div class="notification-list">${ns.map(n=>`<div class="notification" style="${n.read?'opacity:.62':''}"><i>${n.icon}</i><div><b>${esc(n.title)}</b><p>${esc(n.body)}</p><span class="subtle">${esc(n.when)}</span></div>${!n.read?'<span class="notify-dot" style="position:static;margin-left:auto;flex:none"></span>':''}</div>`).join('')||empty('♧','All caught up','Your quest updates will appear here.')}</div></div>`}
function settingsPage(){return `<div class="page-title-row"><div><span class="eyebrow">MAKE IT YOURS</span><h1>Account & settings</h1><p>Your profile, preferences and account details in one place.</p></div></div><div class="card profile-hero">${avatar(user)}<div><h2>${esc(fullName())}</h2><p>${esc(level(user.xp)[0])} · ${user.xp.toLocaleString()} XP &nbsp;·&nbsp; Member since ${new Date(user.joined).toLocaleDateString(undefined,{month:'long',year:'numeric'})}</p></div><div class="profile-level"><b>${Math.round((user.xp-level(user.xp)[1])/(level(user.xp)[2]-level(user.xp)[1])*100)}% to next level</b><span>${Math.max(0,level(user.xp)[2]-user.xp)} XP to ${level(user.xp)[0]==='Rookie'?'Explorer':level(user.xp)[0]==='Explorer'?'Scholar':'Master'}</span></div></div><div class="tabs">${[['profile','Profile'],['photo','Photo'],['security','Security'],['preferences','Preferences'],['danger','Danger zone']].map(([id,label])=>`<button class="tab ${profileTab===id?'active':''}" data-tab="${id}">${label}</button>`).join('')}</div><div class="settings-panel ${profileTab==='profile'?'active':''}"><div class="card form-card"><h3>Personal information</h3><p>Keep your learner profile up to date.</p><form id="profile-form"><div class="form-grid"><div class="field"><label>First name</label><input name="firstName" required value="${esc(user.firstName)}"></div><div class="field"><label>Last name</label><input name="lastName" required value="${esc(user.lastName)}"></div><div class="field wide"><label>Email address</label><input name="email" type="email" required value="${esc(user.email)}"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(user.phone||'')}" placeholder="Add a phone number"></div><div class="field"><label>Country</label><input name="country" value="${esc(user.country||'')}" placeholder="Your country"></div><div class="field wide"><label>About you</label><textarea name="bio" maxlength="240" placeholder="What are you curious about?">${esc(user.bio||'')}</textarea></div></div><button class="btn btn-primary">Save profile</button></form></div></div><div class="settings-panel ${profileTab==='photo'?'active':''}"><div class="card form-card"><h3>Your profile photo</h3><p>Upload an image or paste a hosted image URL. Your photo appears on your certificates.</p><div style="display:flex;align-items:center;gap:14px;margin-bottom:18px">${avatar(user)}<span class="subtle">Square images work best · up to 3 MB</span></div><form id="avatar-form"><div class="field"><label>Upload from your device</label><input type="file" accept="image/*" name="image" style="font-size:11px"></div><div class="field"><label>Or use an image URL</label><input name="avatarUrl" type="url" placeholder="https://example.com/your-photo.jpg" value="${esc(user.avatar||'')}"></div><button class="btn btn-primary">Save photo</button></form></div></div><div class="settings-panel ${profileTab==='security'?'active':''}"><div class="card form-card"><h3>Change password</h3><p>Choose a strong password you don’t use elsewhere.</p><form id="password-form"><div class="field"><label>Current password</label><input type="password" name="current" required autocomplete="current-password"></div><div class="field"><label>New password</label><input type="password" name="next" required minlength="8" autocomplete="new-password"></div><div class="field"><label>Confirm new password</label><input type="password" name="confirm" required minlength="8" autocomplete="new-password"></div><button class="btn btn-primary">Update password</button></form><div class="inline-note" style="margin-top:15px">Password recovery is available from the sign-in page. In production, send a single-use reset link by email.</div></div></div><div class="settings-panel ${profileTab==='preferences'?'active':''}"><div class="card form-card"><h3>Your preferences</h3><p>Choose the updates that help you stay on track.</p><form id="prefs-form"><div class="switch-row"><div><b>Learning reminders</b><p>Friendly reminders to keep your streak alive.</p></div><input class="switch" type="checkbox" name="reminders" ${user.notifications?'checked':''}></div><div class="switch-row"><div><b>Achievement updates</b><p>Get a note when you unlock badges or certificates.</p></div><input class="switch" type="checkbox" name="achievements" ${user.notifications?'checked':''}></div><button class="btn btn-primary" style="margin-top:17px">Save preferences</button></form></div></div><div class="settings-panel ${profileTab==='danger'?'active':''}"><div class="card form-card"><div class="danger-zone"><h4>Delete your account</h4><p>Deleting your account removes your profile, quests and certificates from this browser. This cannot be undone.</p><button class="btn btn-danger" data-action="delete-account">Delete my account</button></div></div></div>`}
function adminPage(){if(user.role!=='admin')return `<div class="page-title-row"><h1>Administration</h1></div><div class="card">${empty('🔒','Admin access required','Sign in with an administrator account to manage the platform.')}</div>`;let users=db.users.filter(u=>(u.firstName+' '+u.lastName+' '+u.email).toLowerCase().includes(adminQuery.toLowerCase()));return `<div class="page-title-row"><div><span class="eyebrow">PLATFORM CONTROL CENTER</span><h1>Administration</h1><p>Manage accounts, platform identity and system preferences.</p></div><span class="tag">Administrator</span></div><div class="grid stats-grid"><div class="card stat-card"><div class="stat-label">Total accounts</div><div class="stat-value">${db.users.length}</div><div class="stat-foot">${db.users.filter(u=>u.active).length} active</div></div><div class="card stat-card"><div class="stat-label">Quests created</div><div class="stat-value">${db.quests.length}</div><div class="stat-foot">Across all learners</div></div><div class="card stat-card"><div class="stat-label">Certificates</div><div class="stat-value">${db.certificates.length}</div><div class="stat-foot">Achievement unlocked</div></div><div class="card stat-card"><div class="stat-label">Learner experience</div><div class="stat-value">${db.users.filter(u=>u.role==='learner').reduce((a,u)=>a+u.xp,0).toLocaleString()}</div><div class="stat-foot">XP earned in the demo</div></div></div><div class="card card-pad" style="margin-bottom:18px"><div class="card-title-row"><div><h3>People & accounts</h3><span class="subtle">Edit profile data, role and access for each account</span></div><button class="btn btn-primary" data-action="add-user">＋ Add learner</button></div><div class="admin-toolbar"><input class="input" id="admin-search" type="search" placeholder="Search name or email…" value="${esc(adminQuery)}"><span class="subtle" style="align-self:center">${users.length} of ${db.users.length}</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Learner</th><th>Role</th><th>XP</th><th>Status</th><th>Joined</th><th>Actions</th></tr></thead><tbody>${users.map(u=>`<tr><td><div class="admin-user">${avatar(u,'avatar small')}<span>${esc(fullName(u))}<small style="display:block;font-size:9px;color:#999bac;font-weight:400;margin-top:3px">${esc(u.email)}</small></span></div></td><td>${esc(u.role)}</td><td>${u.xp.toLocaleString()}</td><td><span class="pill ${u.active?'green':'gray'}">${u.active?'Active':'Paused'}</span></td><td>${new Date(u.joined).toLocaleDateString()}</td><td><button class="btn btn-soft" style="padding:7px 9px;font-size:9px" data-action="edit-user" data-id="${u.id}">Edit account</button></td></tr>`).join('')||'<tr><td colspan="6">No matching accounts.</td></tr>'}</tbody></table></div></div><div class="card card-pad"><div class="card-title-row"><div><h3>Platform identity</h3><span class="subtle">Name, logo, brand color and contact address</span></div></div><form id="brand-form"><div class="form-grid"><div class="field"><label>App name</label><input name="name" required value="${esc(db.brand.name)}"></div><div class="field"><label>Support contact</label><input name="contact" type="email" value="${esc(db.brand.contact)}"></div><div class="field"><label>Accent color</label><input name="accent" type="color" value="${esc(db.brand.accent)}"></div><div class="field"><label>Upload logo</label><input name="image" type="file" accept="image/*" style="font-size:10px"></div><div class="field wide"><label>Or logo image URL</label><input name="logo" type="url" value="${esc(db.brand.logo)}" placeholder="https://example.com/logo.png"></div></div><button class="btn btn-primary">Save platform identity</button></form><div class="inline-note" style="margin-top:16px">For production, user records and passwords belong in the Django database. Passwords are stored as salted hashes; admins can trigger a password reset but should never read user passwords.</div></div>`}
function userModal(id){let u=db.users.find(x=>x.id===id),isNew=!u;u=u||{id:'u'+crypto.randomUUID().slice(0,8),firstName:'',lastName:'',email:'',country:'',phone:'',bio:'',xp:0,streak:0,bestStreak:0,role:'learner',active:true,notifications:true,avatar:''};return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><h3>${isNew?'Add a learner':'Edit account'}</h3><span class="subtle">Update the user’s associated profile and access details.</span></div><button class="modal-close" data-action="close-modal">✕</button></div><form id="admin-user-form" data-id="${u.id}" data-new="${isNew}"><div class="form-grid"><div class="field"><label>First name</label><input name="firstName" required value="${esc(u.firstName)}"></div><div class="field"><label>Last name</label><input name="lastName" required value="${esc(u.lastName)}"></div><div class="field wide"><label>Email</label><input name="email" type="email" required value="${esc(u.email)}"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(u.phone||'')}"></div><div class="field"><label>Country</label><input name="country" value="${esc(u.country||'')}"></div><div class="field wide"><label>Bio</label><textarea name="bio" maxlength="240">${esc(u.bio||'')}</textarea></div><div class="field"><label>Experience points</label><input name="xp" type="number" min="0" value="${u.xp}"></div><div class="field"><label>Current streak</label><input name="streak" type="number" min="0" value="${u.streak||0}"></div><div class="field"><label>Best streak</label><input name="bestStreak" type="number" min="0" value="${u.bestStreak||0}"></div><div class="field"><label>Date of birth</label><input name="dateOfBirth" type="date" value="${esc(u.dateOfBirth||'')}"></div><div class="field"><label>Last active</label><input name="lastActive" type="date" value="${esc(u.lastActive||'')}"></div><div class="field"><label>Role</label><select name="role"><option value="learner" ${u.role==='learner'?'selected':''}>Learner</option><option value="admin" ${u.role==='admin'?'selected':''}>Administrator</option></select></div><div class="field"><label>Account status</label><select name="active"><option value="true" ${u.active?'selected':''}>Active</option><option value="false" ${!u.active?'selected':''}>Paused</option></select></div><div class="field"><label>Email notifications</label><select name="notifications"><option value="true" ${u.notifications?'selected':''}>Enabled</option><option value="false" ${!u.notifications?'selected':''}>Disabled</option></select></div><div class="field"><label>Profile image URL</label><input name="avatar" type="url" value="${esc(u.avatar||'')}"></div><div class="field wide"><label>Upload profile image</label><input name="image" type="file" accept="image/*" style="font-size:10px"></div></div><div class="inline-note">Password changes use a secure reset link. Existing passwords are never displayed to administrators.</div><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:16px"><button type="button" class="btn btn-outline" data-action="close-modal">Cancel</button><button class="btn btn-primary">${isNew?'Create learner':'Save account'}</button></div></form></div></div>`}
function landing(){return `<div class="landing"><header class="landing-nav"><a class="brand" href="#top">${brandLogo()}<span>${brandName()}</span></a><nav class="landing-links"><a href="#how">How it works</a><a href="#features">Features</a><a href="#for-you">Who it’s for</a><a href="#faq">FAQ</a></nav><div style="display:flex;gap:8px"><button class="btn btn-outline" data-action="auth-login">Log in</button><button class="btn btn-primary" data-action="auth-signup">Start for free</button></div></header><section class="landing-hero" id="top"><div class="landing-hero-inner"><div><span class="tag" style="color:#eee8ff;background:#ffffff20">✦ YOUR NOTES. YOUR ADVENTURE.</span><h1>Make learning your next adventure.</h1><p>Turn the things you need to learn into quests worth completing. Build skills, collect XP, and earn a certificate you’ll be proud to share.</p><div class="landing-actions"><button class="btn btn-white" data-action="auth-signup">Start your first quest&nbsp; →</button><a class="btn" href="#how" style="border:1px solid #ffffff55;color:#fff">See how it works</a></div><p style="font-size:10px;margin-top:17px">Free to start · No credit card required</p></div><div class="landing-visual"><div class="float-chip xp">✧ &nbsp;+50 XP earned</div><div class="mock-phone"><div class="phone-top"><span>✦ StudyQuest</span><span>Challenge 2 / 4</span></div><div class="phone-progress"><i></i></div><span style="font-size:8px;color:#8a8ca0">THE SOLAR SYSTEM · LEVEL 2</span><h3>Which planet is known as the Red Planet?</h3><div class="mock-answer">A &nbsp; Jupiter</div><div class="mock-answer selected">B &nbsp; Mars &nbsp; ✓</div><div class="mock-answer">C &nbsp; Neptune</div><div style="margin-top:14px;background:#7358e8;color:#fff;padding:9px;text-align:center;border-radius:9px;font-size:9px;font-weight:700">Check my answer&nbsp; →</div></div><div class="float-chip badge">🏆 &nbsp; New badge unlocked</div></div></div></section><div class="landing-stats"><div><b>${db.users.filter(x=>x.role==='learner').length.toLocaleString()}+</b><span>Learners exploring</span></div><div><b>${db.quests.length.toLocaleString()}+</b><span>Quests created</span></div><div><b>${db.certificates.length.toLocaleString()}+</b><span>Achievements earned</span></div></div><section class="landing-section" id="how"><div class="section-heading"><span class="eyebrow">LEARNING, WITH A LITTLE MAGIC</span><h2>Three steps to your next “I did it!”</h2><p>Start with the ideas you care about. StudyQuest turns them into a hands-on adventure that helps you learn by doing.</p></div><div class="steps-grid"><div class="card"><span class="step-no">01 / GIVE IT A START</span><h3>Bring a topic or your notes</h3><p>Pick a subject you want to understand. Paste notes or upload a study guide to make it yours.</p></div><div class="card"><span class="step-no">02 / LEARN AS YOU PLAY</span><h3>Take on your quest</h3><p>Move through short lessons, answer questions, earn XP and see your progress grow.</p></div><div class="card"><span class="step-no">03 / CELEBRATE THE WIN</span><h3>Earn something you can share</h3><p>Complete your challenge and take away a beautiful certificate with your name on it.</p></div></div></section><section class="showcase"><div class="showcase-inner"><div><span class="eyebrow">YOUR PROGRESS, MADE VISIBLE</span><h2>Small wins. A really good feeling.</h2><p>Collect experience, unlock badges and watch your learning streak grow. Your dashboard turns effort into a clear picture of how far you’ve come.</p><button class="btn btn-primary" data-action="auth-signup">Start collecting wins&nbsp; →</button></div><div class="showcase-box"><div style="display:flex;justify-content:space-between;align-items:center"><div><b>Level 4 · Scholar</b><div class="subtle" style="margin-top:4px">1,280 / 1,500 XP</div></div><span style="font-size:26px">⚡</span></div><div class="progress" style="margin-top:14px"><span style="width:74%"></span></div><div class="showcase-badges"><i>🚀</i><i>🎯</i><i>🔥</i><i>🧠</i><i style="opacity:.35">📚</i></div><div style="margin-top:15px;background:#faf9fe;border-radius:12px;padding:13px"><b style="font-size:10px">TOP LEARNERS THIS WEEK</b><p style="font-size:9px;margin:7px 0 0">🥇 Maya J. &nbsp;&nbsp; 1,520 XP<br>🥈 You &nbsp;&nbsp; 1,280 XP<br>🥉 Jordan L. &nbsp;&nbsp; 940 XP</p></div></div></div></section><section class="landing-section" id="features"><div class="section-heading"><span class="eyebrow">MADE FOR THE WAY YOU LEARN</span><h2>Everything you need to keep going</h2><p>A calmer, more motivating way to understand new ideas and celebrate your progress.</p></div><div class="feature-grid">${[['✦','Quests from your notes','Turn class notes and study guides into bite-sized challenges.'],['🎮','Learn by playing','Try a quick quiz, get helpful explanations and build confidence.'],['⚡','XP, levels and streaks','See your effort add up with every answer and every day.'],['🏅','Badges to unlock','Collect badges for milestones and special achievements.'],['📈','A dashboard that grows','Real activity charts help you notice what’s working.'],['🎓','Certificates to share','Celebrate a finished quest with your name, score and photo.']].map(([i,t,p])=>`<div class="card"><div class="feature-icon">${i}</div><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></section><section class="landing-section" id="for-you" style="padding-top:10px"><div class="section-heading"><span class="eyebrow">A SPACE FOR EVERY CURIOUS MIND</span><h2>Wherever you are in your learning</h2></div><div class="audience-grid">${[['🎒','Students'],['🌱','Self-learners'],['👩🏽‍🏫','Teachers'],['🚀','Bootcamps']].map(([i,t])=>`<div class="card"><i>${i}</i><h3>${t}</h3></div>`).join('')}</div></section><section class="landing-section" id="faq" style="padding-top:12px"><div class="section-heading"><span class="eyebrow">GOOD QUESTIONS</span><h2>Curious about something?</h2></div><div class="faq"><details><summary>Is StudyQuest free to use?</summary><p>Yes. Start exploring for free and build your first learning quests without a credit card.</p></details><details><summary>Do I need to bring my own notes?</summary><p>No. Start with a topic you’re curious about, or paste notes and upload a text or PDF study guide to personalize a quest.</p></details><details><summary>How does the AI work?</summary><p>In the deployed app, a configured Gemini or Groq model can generate lesson content. The app should always keep a friendly fallback when AI credentials aren’t configured.</p></details><details><summary>Can I use StudyQuest on my phone?</summary><p>Yes. Pages, quizzes and account settings are designed to fit small screens with large tap targets and bottom navigation.</p></details><details><summary>What’s on my certificate?</summary><p>Your name, profile image, quest title, score, issue date and a unique verification code.</p></details></div></section><section class="landing-cta"><h2>Ready to make your next big idea stick?</h2><p>Your next adventure is one good question away.</p><button class="btn btn-white" data-action="auth-signup">Create your free account&nbsp; →</button></section><footer class="landing-footer"><div class="footer-inner"><div><a class="brand" href="#top" style="padding:0;margin:0;color:#fff">${brandLogo()}<span>${brandName()}</span></a><p>Make learning feel like progress. Built with care for curious minds everywhere.</p></div><div class="footer-links"><a href="#features">Product</a><a href="#faq">Help & FAQ</a><button data-action="auth-login" style="background:none;border:0;color:inherit">Log in</button><span>Hacktoberfest · Monrovia 2026</span></div></div></footer></div>`}
function authPage(mode='login',msg=''){let signup=mode==='signup',forgot=mode==='forgot';return `<div class="auth-shell"><aside class="auth-art"><a class="brand" href="#top" style="color:#fff;padding:0">${brandLogo()}<span>${brandName()}</span></a><div><span class="tag" style="background:#ffffff20;color:#fff">A BRIGHTER WAY TO LEARN</span><h2>Turn what you study into something you can play.</h2><p>Build momentum one small quest at a time. Your next level is closer than you think.</p></div><span style="font-size:10px;color:#d9d0ff">✦ &nbsp;Your learning journey starts here</span></aside><main class="auth-form-wrap"><div class="auth-form"><div style="font-size:28px;margin-bottom:16px">${signup?'✨':forgot?'🔐':'👋'}</div><h1>${signup?'Create your account':forgot?'Reset your password':'Welcome back'}</h1><p>${signup?'Join curious minds learning one quest at a time.':forgot?'Enter your email and we’ll help you get back into your account.':'Pick up where your last quest left off.'}</p>${msg?`<div class="message">${esc(msg)}</div>`:''}<form id="auth-form" data-mode="${mode}">${signup?`<div class="form-grid"><div class="field"><label>First name</label><input name="firstName" required autocomplete="given-name" placeholder="Alex"></div><div class="field"><label>Last name</label><input name="lastName" required autocomplete="family-name" placeholder="Morgan"></div><div class="field wide"><label>Email address</label><input name="email" type="email" required autocomplete="email" placeholder="you@example.com"></div><div class="field"><label>Phone (optional)</label><input name="phone" type="tel" autocomplete="tel" placeholder="+231 …"></div><div class="field"><label>Country</label><input name="country" placeholder="Liberia"></div></div><div class="field"><label>Password</label><input name="password" type="password" required minlength="8" autocomplete="new-password" placeholder="At least 8 characters"></div><label style="display:flex;gap:9px;align-items:flex-start;font-size:10px;color:#777b91;margin:10px 0 15px"><input type="checkbox" required style="margin-top:1px">I agree to the Terms and Privacy Policy</label>`:forgot?`<div class="field"><label>Email address</label><input name="email" type="email" required autocomplete="email" placeholder="you@example.com"></div>`:`<div class="field"><label>Email address</label><input name="email" type="email" required autocomplete="email" placeholder="you@example.com"></div><div class="field"><div style="display:flex;justify-content:space-between"><label>Password</label><a href="#forgot" class="text-link" data-action="auth-forgot" style="font-size:10px">Forgot password?</a></div><input name="password" type="password" required autocomplete="current-password" placeholder="Your password"></div><label style="display:flex;gap:8px;align-items:center;font-size:10px;color:#777b91;margin-bottom:16px"><input type="checkbox" name="remember" checked> Keep me signed in</label>`}<button class="btn btn-primary btn-block" style="padding:13px">${signup?'Create account':forgot?'Send reset instructions':'Log in'}&nbsp; →</button></form><div class="auth-switch">${signup?'Already have an account?':forgot?'Remembered it?':'New to StudyQuest?'} <a href="#" data-action="${signup?'auth-login':forgot?'auth-login':'auth-signup'}">${signup||forgot?'Log in':'Create a free account'}</a></div>${!signup&&!forgot?'<div class="inline-note" style="margin-top:20px">Demo access · <b>alex@studyquest.demo</b> / <b>studyquest</b><br>Admin demo · <b>admin@studyquest.demo</b> / <b>admin123</b></div>':''}</div></main></div>`}
function handleAuth(e){e.preventDefault();let f=new FormData(e.target),mode=e.target.dataset.mode,email=String(f.get('email')).toLowerCase().trim();if(mode==='forgot'){toast('If that address has an account, password reset instructions will be sent. In demo mode, connect email to enable this.');authPageRender('login','Password recovery is enabled after email is configured.');return}if(mode==='signup'){if(db.users.some(u=>u.email.toLowerCase()===email)){toast('An account with that email already exists.','error');return}let u={id:'u'+crypto.randomUUID().slice(0,8),firstName:String(f.get('firstName')).trim(),lastName:String(f.get('lastName')).trim(),email,password:String(f.get('password')),role:'learner',active:true,avatar:'',bio:'',country:String(f.get('country')||''),phone:String(f.get('phone')||''),joined:new Date().toISOString().slice(0,10),xp:0,streak:0,bestStreak:0,notifications:true};db.users.push(u);db.notifications.unshift({id:crypto.randomUUID(),owner:u.id,icon:'👋',title:`Welcome to ${db.brand.name}!`,body:'Create your first quest and start earning experience.',when:'Just now',read:false});save();setUser(u);page='Dashboard';toast(`Welcome, ${u.firstName}! Your adventure starts now.`);return}let u=db.users.find(x=>x.email.toLowerCase()===email&&x.password===String(f.get('password')));if(!u||!u.active){toast('Those details did not match an active account. Try again.','error');return}setUser(u);page='Dashboard';toast(`Welcome back, ${u.firstName}!`)}
function authPageRender(mode,msg=''){document.querySelector('#app').innerHTML=authPage(mode,msg)}
function pageContent(){switch(page){case'Dashboard':return dashboard();case'Quests':return questsPage();case'Play quest':return quizPage();case'Certificates':return certsPage();case'Leaderboard':return leaderboard();case'Notifications':return noticesPage();case'Settings':return settingsPage();case'Administration':return adminPage();default:return dashboard()}}
function render(){document.documentElement.style.setProperty('--violet',db.brand.accent||'#7258e8');document.title=`${db.brand.name} — Make learning your next adventure`;if(!user){document.querySelector('#app').innerHTML=landing();drawCharts();return}document.querySelector('#app').innerHTML=shell(pageContent());drawCharts()}
function navigate(p){page=p;mobileOpen=false;if(p==='Notifications'){myNotices().forEach(n=>n.read=true);save()}render();window.scrollTo(0,0)}
function drawCharts(){let c=document.querySelector('#progress-chart');if(!c)return;let ctx=c.getContext('2d'),rect=c.getBoundingClientRect(),dpr=window.devicePixelRatio||1;c.width=rect.width*dpr;c.height=rect.height*dpr;ctx.scale(dpr,dpr);let w=rect.width,h=rect.height,pad={l:26,r:8,t:12,b:23},vals=db.activity.slice(-14),max=Math.max(100,...vals)*1.12;ctx.font='9px DM Sans';ctx.textAlign='right';ctx.fillStyle='#a0a2b0';for(let i=0;i<4;i++){let y=pad.t+(h-pad.t-pad.b)*i/3;ctx.fillText(Math.round(max*(1-i/3)),pad.l-7,y+3);ctx.strokeStyle='#f0f0f5';ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke()}let points=vals.map((v,i)=>({x:pad.l+i*(w-pad.l-pad.r)/(vals.length-1),y:pad.t+(h-pad.t-pad.b)*(1-v/max)}));let grad=ctx.createLinearGradient(0,pad.t,0,h-pad.b);grad.addColorStop(0,'#8e73ef33');grad.addColorStop(1,'#8e73ef00');ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.lineTo(points.at(-1).x,h-pad.b);ctx.lineTo(points[0].x,h-pad.b);ctx.closePath();ctx.fillStyle=grad;ctx.fill();ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle='#755be6';ctx.lineWidth=2.5;ctx.lineJoin='round';ctx.stroke();points.forEach((p,i)=>{ctx.beginPath();ctx.arc(p.x,p.y,3,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();ctx.strokeStyle='#755be6';ctx.lineWidth=2;ctx.stroke();if(i%2===0||i===points.length-1){ctx.fillStyle='#a0a2b0';ctx.font='9px DM Sans';ctx.textAlign='center';ctx.fillText(`${i+1}`,p.x,h-5)}})}
function closeModal(){document.querySelector('.modal-backdrop')?.remove()}
function printCert(id){let c=myCerts().find(x=>x.id===id);if(!c)return;let w=window.open('','_blank','width=900,height=700');if(!w){toast('Allow pop-ups to open your certificate.','error');return}let portrait=user.avatar?`<img class="portrait" src="${esc(user.avatar)}" alt="${esc(fullName())}">`:`<div class="portrait initials">${esc(initials())}</div>`;w.document.write(`<!doctype html><html><head><title>${esc(c.code)} · ${esc(db.brand.name)}</title><style>body{margin:0;background:#f7f5ef;font-family:Georgia,serif}.certificate{margin:35px auto;width:850px;height:540px;box-sizing:border-box;border:10px double #c6a953;outline:1px solid #c6a953;outline-offset:-19px;background:#fffdf8;text-align:center;padding:38px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#312c50}.brand{font:700 13px Arial;letter-spacing:3px;text-transform:uppercase;color:#826a2c}.laurel{font-size:29px;margin:7px}.pre{font:italic 14px Arial;color:#747183}.portrait{height:62px;width:62px;border-radius:50%;object-fit:cover;margin:7px;border:2px solid #c6a953}.initials{display:grid;place-items:center;background:#eee9fb;color:#7258e8;font:700 19px Arial}.name{font:italic 34px Georgia;margin:4px}.title{font:700 21px Georgia;color:#7258e8}.stats{display:flex;gap:55px;margin:19px}.stats b{font:700 16px Arial}.stats small{display:block;color:#8b8997;font:9px Arial;margin-top:5px;letter-spacing:1px}.foot{display:flex;justify-content:space-between;width:92%;font:11px Arial;color:#777}.code{font:9px Arial;color:#888;margin-top:11px}@media print{body{background:#fff}.certificate{margin:0;width:100vw;height:100vh}}</style></head><body><main class="certificate"><div class="brand">${esc(db.brand.name)} · Certificate of achievement</div><div class="laurel">✦ &nbsp;🏅&nbsp; ✦</div><div class="pre">This certificate is proudly presented to</div>${portrait}<div class="name">${esc(fullName())}</div><div class="pre">for successfully completing the learning quest</div><div class="title">${esc(c.questTitle)}</div><div class="stats"><div><b>${c.score}%</b><small>QUEST SCORE</small></div><div><b>${user.xp.toLocaleString()}</b><small>TOTAL XP</small></div><div><b>${esc(level(user.xp)[0])}</b><small>LEARNER RANK</small></div></div><div class="foot"><span>Issued ${new Date(c.issued+'T12:00:00').toLocaleDateString(undefined,{day:'numeric',month:'long',year:'numeric'})}</span><span>${esc(fullName())} · ${esc(db.brand.name)}</span></div><div class="code">Certificate ID: ${esc(c.code)} · Verify at ${location.origin}/#verify/${esc(c.code)}</div></main><script>window.onload=()=>setTimeout(()=>window.print(),400)</script></body></html>`);w.document.close()}
function showUserModal(id){document.body.insertAdjacentHTML('beforeend',userModal(id))}
function accountForm(e){e.preventDefault();let f=new FormData(e.target),id=e.target.dataset.id,isNew=e.target.dataset.new==='true',target=db.users.find(u=>u.id===id);let email=String(f.get('email')).trim().toLowerCase();if(db.users.some(u=>u.email.toLowerCase()===email&&u.id!==id)){toast('That email already belongs to another account.','error');return}let image=f.get('image'),apply=data=>{let obj={...(target||{}),id,firstName:String(f.get('firstName')).trim(),lastName:String(f.get('lastName')).trim(),email,phone:String(f.get('phone')||''),country:String(f.get('country')||''),bio:String(f.get('bio')||''),xp:Math.max(0,Number(f.get('xp'))||0),streak:Math.max(0,Number(f.get('streak'))||0),bestStreak:Math.max(0,Number(f.get('bestStreak'))||0),dateOfBirth:String(f.get('dateOfBirth')||''),lastActive:String(f.get('lastActive')||''),notifications:f.get('notifications')==='true',role:String(f.get('role')),active:f.get('active')==='true',avatar:data||String(f.get('avatar')||target?.avatar||''),joined:target?.joined||new Date().toISOString().slice(0,10),password:target?.password||('welcome'+crypto.randomUUID().slice(0,5))};if(isNew)db.users.push(obj);else Object.assign(target,obj);save();closeModal();render();toast(isNew?'Learner created. A secure invitation/reset flow is needed for production.':'Account details updated.')};if(image?.size){if(image.size>3*1024*1024){toast('Image must be smaller than 3 MB.','error');return}let r=new FileReader();r.onload=()=>apply(r.result);r.readAsDataURL(image)}else apply('')}
document.addEventListener('click',e=>{let pageEl=e.target.closest('[data-page]');if(pageEl){e.preventDefault();navigate(pageEl.dataset.page);return}let mode=e.target.closest('[data-mode]');if(mode){questMode=mode.dataset.mode;document.querySelector('.modal-backdrop')?.remove();document.body.insertAdjacentHTML('beforeend',newQuestModal());return}let tab=e.target.closest('[data-tab]');if(tab){profileTab=tab.dataset.tab;render();return}let answer=e.target.closest('[data-answer]');if(answer&&activeQuiz){let i=Number(answer.dataset.answer);if(quizAnswers[quizStep]!==undefined)return;quizAnswers[quizStep]=i;let correct=activeQuiz.questions[quizStep]?.correct===i;user.xp+=correct?10:2;save();render();return}let actionEl=e.target.closest('[data-action]');if(actionEl?.classList.contains('modal-backdrop')&&e.target!==actionEl)actionEl=null;let action=actionEl?.dataset.action;if(!action)return;switch(action){case'menu':mobileOpen=!mobileOpen;render();break;case'landing':user=null;sessionStorage.removeItem('sq.user');page='Dashboard';render();break;case'logout':user=null;sessionStorage.removeItem('sq.user');page='Dashboard';render();break;case'new-quest':questMode='topic';document.body.insertAdjacentHTML('beforeend',newQuestModal());break;case'close-modal':closeModal();break;case'play':playQuest(e.target.closest('[data-id]').dataset.id);break;case'next-question':if(quizStep<activeQuiz.questions.length-1){quizStep++;render()}else finishQuiz();break;case'read-all':myNotices().forEach(n=>n.read=true);save();render();toast('All notifications marked as read.');break;case'print-cert':printCert(e.target.closest('[data-id]').dataset.id);break;case'edit-user':showUserModal(e.target.closest('[data-id]').dataset.id);break;case'add-user':showUserModal(null);break;case'auth-login':user=null;document.querySelectorAll('.modal-backdrop').forEach(m=>m.remove());authPageRender('login');break;case'auth-signup':user=null;document.querySelectorAll('.modal-backdrop').forEach(m=>m.remove());authPageRender('signup');break;case'auth-forgot':user=null;document.querySelectorAll('.modal-backdrop').forEach(m=>m.remove());authPageRender('forgot');break;case'delete-account':if(confirm('Delete this account and its learning history? This cannot be undone.')){db.users=db.users.filter(u=>u.id!==user.id);db.quests=db.quests.filter(q=>q.owner!==user.id);db.certificates=db.certificates.filter(c=>c.owner!==user.id);db.notifications=db.notifications.filter(n=>n.owner!==user.id);save();user=null;sessionStorage.removeItem('sq.user');render();toast('Your account has been removed.')};break;case'view-verify':break}});
document.addEventListener('submit',e=>{if(e.target.id==='quest-form'){startQuest(e);return}if(e.target.id==='auth-form'){handleAuth(e);return}if(e.target.id==='profile-form'){e.preventDefault();let f=new FormData(e.target),email=String(f.get('email')).toLowerCase().trim();if(db.users.some(u=>u.email.toLowerCase()===email&&u.id!==user.id)){toast('That email already belongs to another account.','error');return}Object.assign(user,{firstName:String(f.get('firstName')).trim(),lastName:String(f.get('lastName')).trim(),email,phone:String(f.get('phone')||''),country:String(f.get('country')||''),bio:String(f.get('bio')||'')});save();render();toast('Your profile is up to date.');return}if(e.target.id==='avatar-form'){e.preventDefault();let f=new FormData(e.target),file=f.get('image'),url=String(f.get('avatarUrl')||'').trim();if(file?.size){if(file.size>3*1024*1024){toast('Choose an image smaller than 3 MB.','error');return}let reader=new FileReader();reader.onload=()=>{user.avatar=reader.result;save();render();toast('Your profile photo is updated.')};reader.readAsDataURL(file)}else if(url){user.avatar=url;save();render();toast('Your profile photo is updated.')}else toast('Choose an image or paste an image URL.','error');return}if(e.target.id==='password-form'){e.preventDefault();let f=new FormData(e.target);if(String(f.get('current'))!==user.password){toast('Your current password did not match.','error');return}if(f.get('next')!==f.get('confirm')){toast('The new passwords do not match.','error');return}user.password=String(f.get('next'));save();render();toast('Password updated.');return}if(e.target.id==='prefs-form'){e.preventDefault();user.notifications=new FormData(e.target).has('reminders')||new FormData(e.target).has('achievements');save();render();toast('Your preferences were saved.');return}if(e.target.id==='admin-user-form'){accountForm(e);return}if(e.target.id==='brand-form'){e.preventDefault();let f=new FormData(e.target),file=f.get('image'),apply=data=>{db.brand.name=String(f.get('name')).trim();db.brand.contact=String(f.get('contact')||'');db.brand.accent=String(f.get('accent')||'#7258e8');db.brand.logo=data||String(f.get('logo')||'');save();render();toast('Platform identity updated.')};if(file?.size){if(file.size>3*1024*1024){toast('Logo image must be smaller than 3 MB.','error');return}let r=new FileReader();r.onload=()=>apply(r.result);r.readAsDataURL(file)}else apply('');return}});
document.addEventListener('input',e=>{if(e.target.id==='admin-search'){adminQuery=e.target.value;let pos=e.target.selectionStart;render();let n=document.querySelector('#admin-search');n?.focus();n?.setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{if(e.target.id==='chart-range'){if(e.target.value==='Last 7 days')db.activity=db.activity.slice(-7);else db.activity=(db.activity.length<14?[...seed.activity]:db.activity).slice(-14);drawCharts()}});
window.addEventListener('resize',()=>drawCharts());
window.addEventListener('hashchange',()=>{let route=decodeURIComponent(location.hash.slice(1));if(route.startsWith('verify/')){let code=route.split('/')[1],cert=db.certificates.find(c=>c.code===code);document.querySelector('#app').innerHTML=`<div class="auth-shell"><main class="auth-form-wrap"><div class="auth-form" style="text-align:center"><div style="font-size:48px">${cert?'✅':'🔎'}</div><h1>${cert?'Certificate verified':'Certificate not found'}</h1>${cert?`<p>${esc(fullName(db.users.find(u=>u.id===cert.owner)||{}))} completed <b>${esc(cert.questTitle)}</b> with a score of ${cert.score}%. Certificate ID ${esc(cert.code)}.</p>`:'<p>We could not find a certificate with that verification code.</p>'}<a class="btn btn-primary" href="#dashboard" data-action="auth-login">Go to StudyQuest</a></div></main></div>`}});
render();
